    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; cells=[]
                seen.add((r,c))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
