from collections import Counter
def shp(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; cells=[]; seen.add((r,c))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                pat=(col,tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells)))
                out.append((pat,(min(ys),min(xs))))
    return out
