def norm(pat):
    h=max(p[0] for p in pat)+1; w=max(p[1] for p in pat)+1
    s=frozenset(pat)
    def tf(cells,h,w,fr,fc):
        return frozenset(sorted(fr(y,x) for y,x in cells))
    variants=[s,
        frozenset((y,w-1-x) for y,x in s),        # mirror h
        frozenset((h-1-y,x) for y,x in s),        # mirror v
        frozenset((h-1-y,w-1-x) for y,x in s),    # rot180
        frozenset((x,y) for y,x in s),            # transpose
        frozenset((x,h-1-y) for y,x in s),        # transpose+flip
        frozenset((w-1-x,y) for y,x in s),
        frozenset((w-1-x,h-1-y) for y,x in s)]
    return min(variants)
